// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 blockNum1, uint256 blockNum2, uint8 timestampSame) public {
        vm.assume(amount1 == 10 ether);
        vm.assume(amount2 == 10 ether);

        uint256 ts1 = block.timestamp;
        vm.warp(ts1);
        vm.roll(blockNum1);
        vm.deal(address(this), amount1);
        (bool ok1,) = address(c).call{value: amount1}("");
        vm.assume(ok1);

        uint256 ts2 = timestampSame > 0 ? ts1 : ts1 + 1;
        vm.warp(ts2);
        vm.roll(blockNum2);
        vm.deal(address(this), amount2);
        (bool ok2,) = address(c).call{value: amount2}("");

        if (ts2 == ts1) {
            assertFalse(ok2);
        }
    }
}
